static SynurangLiteStatus volvoxai_v1_adapter_revision_encode_into(
    const VolvoxaiV1AdapterRevision* message,
    SynurangLiteWriterInternal* writer) {
    SynurangLiteStatus status = SYNURANG_LITE_OK;
    size_t i;
    if (!message || !writer) return SYNURANG_LITE_INVALID_ARGUMENT;
    (void)status;
    if (message->field_adapter_id != 0) {
        sl_write_uint64(
            writer, 1, message->field_adapter_id);
    }
    if (message->field_adapter_revision != 0) {
        sl_write_uint64(
            writer, 2, message->field_adapter_revision);
    }
    if (message->field_report) {
        uint8_t* nested = NULL;
        size_t nested_len = 0;
        status = volvoxai_v1_operation_report_encode(
            message->field_report, &nested, &nested_len);
        if (status != SYNURANG_LITE_OK) return status;
        sl_write_length_delimited(writer, 3, nested, nested_len);
        synurang_lite_release(message->field_report->_allocator, nested);
    }
    (void)i;
    return writer->status;
}

SynurangLiteStatus volvoxai_v1_adapter_revision_encode(
    const VolvoxaiV1AdapterRevision* message,
    uint8_t** output,
    size_t* output_len) {
    SynurangLiteWriterInternal writer;
    if (!message || !output || !output_len) return SYNURANG_LITE_INVALID_ARGUMENT;
    *output = NULL;
    *output_len = 0;
    sl_writer_init(&writer, message->_allocator);
    writer.status = volvoxai_v1_adapter_revision_encode_into(message, &writer);
    if (writer.status != SYNURANG_LITE_OK) {
        SynurangLiteStatus status = writer.status;
        sl_writer_discard(&writer);
        return status;
    }
    *output = writer.data;
    *output_len = writer.len;
    return SYNURANG_LITE_OK;
}


