uint64_t* volvoxai_v1_allocate_buffers_request_add_sizes_bytes(
    VolvoxaiV1AllocateBuffersRequest* message) {
    const SynurangLiteAllocator* allocator;
    uint64_t* grown;
    size_t capacity;

    if (!message) return NULL;
    allocator = synurang_lite_allocator_or_default(message->_allocator);
    if (message->field_sizes_bytes.len == message->field_sizes_bytes.cap) {
        /* The allocator has no realloc, so growth allocates, copies, frees.
         * Doubling keeps repeated appends amortized. */
        capacity = message->field_sizes_bytes.cap ? message->field_sizes_bytes.cap * 2u : 4u;
        if (capacity < message->field_sizes_bytes.cap ||
            capacity > SIZE_MAX / sizeof(*grown)) return NULL;
        grown = (uint64_t*)allocator->allocate(
            allocator->context, sizeof(*grown) * capacity);
        if (!grown) return NULL;
        memset(grown, 0, sizeof(*grown) * capacity);
        if (message->field_sizes_bytes.len) {
            memcpy(grown, message->field_sizes_bytes.data,
                   sizeof(*grown) * message->field_sizes_bytes.len);
        }
        synurang_lite_release(allocator, message->field_sizes_bytes.data);
        message->field_sizes_bytes.data = grown;
        message->field_sizes_bytes.cap = capacity;
    }
    {
        uint64_t* slot =
            &message->field_sizes_bytes.data[message->field_sizes_bytes.len];
        memset(slot, 0, sizeof(*slot));
        message->field_sizes_bytes.len++;
        return slot;
    }
}

