VolvoxaiV1BatchValue* volvoxai_v1_batch_work_info_add_values(
    VolvoxaiV1BatchWorkInfo* message) {
    const SynurangLiteAllocator* allocator;
    VolvoxaiV1BatchValue* grown;
    size_t capacity;

    if (!message) return NULL;
    allocator = synurang_lite_allocator_or_default(message->_allocator);
    if (message->field_values.len == message->field_values.cap) {
        /* The allocator has no realloc, so growth allocates, copies, frees.
         * Doubling keeps repeated appends amortized. */
        capacity = message->field_values.cap ? message->field_values.cap * 2u : 4u;
        if (capacity < message->field_values.cap ||
            capacity > SIZE_MAX / sizeof(*grown)) return NULL;
        grown = (VolvoxaiV1BatchValue*)allocator->allocate(
            allocator->context, sizeof(*grown) * capacity);
        if (!grown) return NULL;
        memset(grown, 0, sizeof(*grown) * capacity);
        if (message->field_values.len) {
            memcpy(grown, message->field_values.data,
                   sizeof(*grown) * message->field_values.len);
        }
        synurang_lite_release(allocator, message->field_values.data);
        message->field_values.data = grown;
        message->field_values.cap = capacity;
    }
    {
        VolvoxaiV1BatchValue* slot =
            &message->field_values.data[message->field_values.len];
        memset(slot, 0, sizeof(*slot));
        volvoxai_v1_batch_value_init_with_allocator(slot, allocator);
        message->field_values.len++;
        return slot;
    }
}
