static SynurangLiteStatus volvoxai_v1_decode_cache_lane_merge_reader(
    VolvoxaiV1DecodeCacheLane* message,
    SynurangLiteReaderInternal* reader,
    unsigned int message_depth) {
    SynurangLiteStatus status = SYNURANG_LITE_OK;
    uint32_t field_number;
    uint8_t wire_type;
    int tag_result;
    if (!message || !reader) return SYNURANG_LITE_INVALID_ARGUMENT;
    if (message_depth > SYNURANG_LITE_MAX_MESSAGE_DEPTH) {
        return SYNURANG_LITE_MALFORMED;
    }
    (void)status;
    while ((tag_result = sl_read_tag(reader, &field_number, &wire_type)) > 0) {
        switch (field_number) {
            case 1:
                if (!sl_read_uint32(
                        reader, wire_type, &message->field_active_length)) break;
                break;
            case 2:
                if (!sl_read_uint32(
                        reader, wire_type, &message->field_generation)) break;
                break;
            case 3:
            {
                void* appended;
                if (wire_type == 2) {
                    const uint8_t* packed_data;
                    size_t packed_len;
                    SynurangLiteReaderInternal packed;
                    if (!sl_read_slice(reader, &packed_data, &packed_len)) break;
                    sl_reader_init(&packed, packed_data, packed_len);
                    while (packed.pos < packed.len) {
                        status = sl_array_append(
                            message->_allocator,
                            (void**)&message->field_pages.data,
                            &message->field_pages.len,
                            &message->field_pages.cap,
                            sizeof(*message->field_pages.data),
                            &appended);
                        if (status != SYNURANG_LITE_OK) return status;
                        if (!sl_read_int32_raw(
                                &packed,
                                (int32_t*)appended)) break;
                    }
                    if (packed.status != SYNURANG_LITE_OK || packed.pos != packed.len) {
                        reader->status = packed.status == SYNURANG_LITE_OK
                            ? SYNURANG_LITE_MALFORMED : packed.status;
                    }
                } else {
                    status = sl_array_append(
                        message->_allocator,
                        (void**)&message->field_pages.data,
                        &message->field_pages.len,
                        &message->field_pages.cap,
                        sizeof(*message->field_pages.data),
                        &appended);
                    if (status != SYNURANG_LITE_OK) return status;
                    if (!sl_read_int32(
                            reader,
                            wire_type,
                            (int32_t*)appended)) break;
                }
                break;
            }
            default:
                if (wire_type == 4 || !sl_skip_field(reader, field_number, wire_type)) {
                    reader->status = SYNURANG_LITE_MALFORMED;
                }
                break;
        }
        if (reader->status != SYNURANG_LITE_OK) break;
    }
    if (tag_result < 0 || reader->status != SYNURANG_LITE_OK) return reader->status;
    return reader->pos == reader->len ? SYNURANG_LITE_OK : SYNURANG_LITE_MALFORMED;
}

SynurangLiteStatus volvoxai_v1_decode_cache_lane_decode(
    VolvoxaiV1DecodeCacheLane* message,
    const uint8_t* data,
    size_t len) {
    VolvoxaiV1DecodeCacheLane temporary;
    SynurangLiteReaderInternal reader;
    SynurangLiteStatus status;
    if (!message || (!data && len != 0)) return SYNURANG_LITE_INVALID_ARGUMENT;
    volvoxai_v1_decode_cache_lane_init_with_allocator(&temporary, message->_allocator);
    sl_reader_init(&reader, data, len);
    status = volvoxai_v1_decode_cache_lane_merge_reader(&temporary, &reader, 0);
    if (status != SYNURANG_LITE_OK) {
        volvoxai_v1_decode_cache_lane_free(&temporary);
        return status;
    }
    volvoxai_v1_decode_cache_lane_free(message);
    *message = temporary;
    return SYNURANG_LITE_OK;
}
int32_t* volvoxai_v1_decode_cache_lane_add_pages(
    VolvoxaiV1DecodeCacheLane* message) {
    const SynurangLiteAllocator* allocator;
    int32_t* grown;
    size_t capacity;

    if (!message) return NULL;
    allocator = synurang_lite_allocator_or_default(message->_allocator);
    if (message->field_pages.len == message->field_pages.cap) {
        /* The allocator has no realloc, so growth allocates, copies, frees.
         * Doubling keeps repeated appends amortized. */
        capacity = message->field_pages.cap ? message->field_pages.cap * 2u : 4u;
        if (capacity < message->field_pages.cap ||
            capacity > SIZE_MAX / sizeof(*grown)) return NULL;
        grown = (int32_t*)allocator->allocate(
            allocator->context, sizeof(*grown) * capacity);
        if (!grown) return NULL;
        memset(grown, 0, sizeof(*grown) * capacity);
        if (message->field_pages.len) {
            memcpy(grown, message->field_pages.data,
                   sizeof(*grown) * message->field_pages.len);
        }
        synurang_lite_release(allocator, message->field_pages.data);
        message->field_pages.data = grown;
        message->field_pages.cap = capacity;
    }
    {
        int32_t* slot =
            &message->field_pages.data[message->field_pages.len];
        memset(slot, 0, sizeof(*slot));
        message->field_pages.len++;
        return slot;
    }
}

