uint32_t* volvoxai_v1_decode_context_state_add_active_lengths(
    VolvoxaiV1DecodeContextState* message) {
    const SynurangLiteAllocator* allocator;
    uint32_t* grown;
    size_t capacity;

    if (!message) return NULL;
    allocator = synurang_lite_allocator_or_default(message->_allocator);
    if (message->field_active_lengths.len == message->field_active_lengths.cap) {
        /* The allocator has no realloc, so growth allocates, copies, frees.
         * Doubling keeps repeated appends amortized. */
        capacity = message->field_active_lengths.cap ? message->field_active_lengths.cap * 2u : 4u;
        if (capacity < message->field_active_lengths.cap ||
            capacity > SIZE_MAX / sizeof(*grown)) return NULL;
        grown = (uint32_t*)allocator->allocate(
            allocator->context, sizeof(*grown) * capacity);
        if (!grown) return NULL;
        memset(grown, 0, sizeof(*grown) * capacity);
        if (message->field_active_lengths.len) {
            memcpy(grown, message->field_active_lengths.data,
                   sizeof(*grown) * message->field_active_lengths.len);
        }
        synurang_lite_release(allocator, message->field_active_lengths.data);
        message->field_active_lengths.data = grown;
        message->field_active_lengths.cap = capacity;
    }
    {
        uint32_t* slot =
            &message->field_active_lengths.data[message->field_active_lengths.len];
        memset(slot, 0, sizeof(*slot));
        message->field_active_lengths.len++;
        return slot;
    }
}
