int32_t* volvoxai_v1_decode_lane_positions_add_positions(
    VolvoxaiV1DecodeLanePositions* message) {
    const SynurangLiteAllocator* allocator;
    int32_t* grown;
    size_t capacity;

    if (!message) return NULL;
    allocator = synurang_lite_allocator_or_default(message->_allocator);
    if (message->field_positions.len == message->field_positions.cap) {
        /* The allocator has no realloc, so growth allocates, copies, frees.
         * Doubling keeps repeated appends amortized. */
        capacity = message->field_positions.cap ? message->field_positions.cap * 2u : 4u;
        if (capacity < message->field_positions.cap ||
            capacity > SIZE_MAX / sizeof(*grown)) return NULL;
        grown = (int32_t*)allocator->allocate(
            allocator->context, sizeof(*grown) * capacity);
        if (!grown) return NULL;
        memset(grown, 0, sizeof(*grown) * capacity);
        if (message->field_positions.len) {
            memcpy(grown, message->field_positions.data,
                   sizeof(*grown) * message->field_positions.len);
        }
        synurang_lite_release(allocator, message->field_positions.data);
        message->field_positions.data = grown;
        message->field_positions.cap = capacity;
    }
    {
        int32_t* slot =
            &message->field_positions.data[message->field_positions.len];
        memset(slot, 0, sizeof(*slot));
        message->field_positions.len++;
        return slot;
    }
}

