VolvoxaiV1MemoryBoundProof* volvoxai_v1_memory_domain_attestation_add_bounds(
    VolvoxaiV1MemoryDomainAttestation* message) {
    const SynurangLiteAllocator* allocator;
    VolvoxaiV1MemoryBoundProof* grown;
    size_t capacity;

    if (!message) return NULL;
    allocator = synurang_lite_allocator_or_default(message->_allocator);
    if (message->field_bounds.len == message->field_bounds.cap) {
        /* The allocator has no realloc, so growth allocates, copies, frees.
         * Doubling keeps repeated appends amortized. */
        capacity = message->field_bounds.cap ? message->field_bounds.cap * 2u : 4u;
        if (capacity < message->field_bounds.cap ||
            capacity > SIZE_MAX / sizeof(*grown)) return NULL;
        grown = (VolvoxaiV1MemoryBoundProof*)allocator->allocate(
            allocator->context, sizeof(*grown) * capacity);
        if (!grown) return NULL;
        memset(grown, 0, sizeof(*grown) * capacity);
        if (message->field_bounds.len) {
            memcpy(grown, message->field_bounds.data,
                   sizeof(*grown) * message->field_bounds.len);
        }
        synurang_lite_release(allocator, message->field_bounds.data);
        message->field_bounds.data = grown;
        message->field_bounds.cap = capacity;
    }
    {
        VolvoxaiV1MemoryBoundProof* slot =
            &message->field_bounds.data[message->field_bounds.len];
        memset(slot, 0, sizeof(*slot));
        volvoxai_v1_memory_bound_proof_init_with_allocator(slot, allocator);
        message->field_bounds.len++;
        return slot;
    }
}

