VolvoxaiV1MemoryResourceEvidence* volvoxai_v1_memory_snapshot_add_resources(
    VolvoxaiV1MemorySnapshot* message) {
    const SynurangLiteAllocator* allocator;
    VolvoxaiV1MemoryResourceEvidence* grown;
    size_t capacity;

    if (!message) return NULL;
    allocator = synurang_lite_allocator_or_default(message->_allocator);
    if (message->field_resources.len == message->field_resources.cap) {
        /* The allocator has no realloc, so growth allocates, copies, frees.
         * Doubling keeps repeated appends amortized. */
        capacity = message->field_resources.cap ? message->field_resources.cap * 2u : 4u;
        if (capacity < message->field_resources.cap ||
            capacity > SIZE_MAX / sizeof(*grown)) return NULL;
        grown = (VolvoxaiV1MemoryResourceEvidence*)allocator->allocate(
            allocator->context, sizeof(*grown) * capacity);
        if (!grown) return NULL;
        memset(grown, 0, sizeof(*grown) * capacity);
        if (message->field_resources.len) {
            memcpy(grown, message->field_resources.data,
                   sizeof(*grown) * message->field_resources.len);
        }
        synurang_lite_release(allocator, message->field_resources.data);
        message->field_resources.data = grown;
        message->field_resources.cap = capacity;
    }
    {
        VolvoxaiV1MemoryResourceEvidence* slot =
            &message->field_resources.data[message->field_resources.len];
        memset(slot, 0, sizeof(*slot));
        volvoxai_v1_memory_resource_evidence_init_with_allocator(slot, allocator);
        message->field_resources.len++;
        return slot;
    }
}
