static SynurangLiteStatus volvoxai_v1_runtime_budget_merge_reader(
    VolvoxaiV1RuntimeBudget* message,
    SynurangLiteReaderInternal* reader,
    unsigned int message_depth) {
    SynurangLiteStatus status = SYNURANG_LITE_OK;
    uint32_t field_number;
    uint8_t wire_type;
    int tag_result;
    if (!message || !reader) return SYNURANG_LITE_INVALID_ARGUMENT;
    if (message_depth > SYNURANG_LITE_MAX_MESSAGE_DEPTH) {
        return SYNURANG_LITE_MALFORMED;
    }
    (void)status;
    while ((tag_result = sl_read_tag(reader, &field_number, &wire_type)) > 0) {
        switch (field_number) {
            case 1:
                if (!sl_read_uint64(
                        reader, wire_type, &message->field_max_scheduled_requests)) break;
                message->has_max_scheduled_requests = 1;
                break;
            case 2:
                if (!sl_read_uint64(
                        reader, wire_type, &message->field_max_scheduled_input_bytes)) break;
                message->has_max_scheduled_input_bytes = 1;
                break;
            case 3:
                if (!sl_read_uint64(
                        reader, wire_type, &message->field_max_batch_delay_ns)) break;
                message->has_max_batch_delay_ns = 1;
                break;
            case 4:
                if (!sl_read_uint64(
                        reader, wire_type, &message->field_max_unconsumed_results)) break;
                message->has_max_unconsumed_results = 1;
                break;
            case 5:
                if (!sl_read_uint64(
                        reader, wire_type, &message->field_max_unconsumed_result_bytes)) break;
                message->has_max_unconsumed_result_bytes = 1;
                break;
            default:
                if (wire_type == 4 || !sl_skip_field(reader, field_number, wire_type)) {
                    reader->status = SYNURANG_LITE_MALFORMED;
                }
                break;
        }
        if (reader->status != SYNURANG_LITE_OK) break;
    }
    if (tag_result < 0 || reader->status != SYNURANG_LITE_OK) return reader->status;
    return reader->pos == reader->len ? SYNURANG_LITE_OK : SYNURANG_LITE_MALFORMED;
}

