static SynurangLiteStatus volvoxai_v1_submit_batch_work_request_merge_reader(
    VolvoxaiV1SubmitBatchWorkRequest* message,
    SynurangLiteReaderInternal* reader,
    unsigned int message_depth) {
    SynurangLiteStatus status = SYNURANG_LITE_OK;
    uint32_t field_number;
    uint8_t wire_type;
    int tag_result;
    if (!message || !reader) return SYNURANG_LITE_INVALID_ARGUMENT;
    if (message_depth > SYNURANG_LITE_MAX_MESSAGE_DEPTH) {
        return SYNURANG_LITE_MALFORMED;
    }
    (void)status;
    while ((tag_result = sl_read_tag(reader, &field_number, &wire_type)) > 0) {
        switch (field_number) {
            case 1:
                if (!sl_read_int64(
                        reader, wire_type, &message->field_queue_id)) break;
                break;
            case 2:
            {
                const uint8_t* value_data;
                size_t value_len;
                if (!sl_expect_wire(reader, wire_type, 2) ||
                    !sl_read_slice(reader, &value_data, &value_len)) break;
                if (!message->field_group) {
                    message->field_group =
                        (VolvoxaiV1BatchGroup*)message->_allocator->allocate(
                            message->_allocator->context,
                            sizeof(*message->field_group));
                    if (!message->field_group) return SYNURANG_LITE_OUT_OF_MEMORY;
                    volvoxai_v1_batch_group_init_with_allocator(
                        message->field_group, message->_allocator);
                }
                status = volvoxai_v1_batch_group_merge_at_depth(
                    message->field_group, value_data, value_len,
                    message_depth + 1);
                if (status != SYNURANG_LITE_OK) return status;
                break;
            }
            case 3:
            {
                const uint8_t* value_data;
                size_t value_len;
                if (!sl_expect_wire(reader, wire_type, 2) ||
                    !sl_read_slice(reader, &value_data, &value_len)) break;
                status = synurang_lite_bytes_assign(
                    message->_allocator,
                    &message->field_payload,
                    value_data,
                    value_len);
                if (status != SYNURANG_LITE_OK) return status;
                break;
            }
            case 4:
            {
                const uint8_t* value_data;
                size_t value_len;
                if (!sl_expect_wire(reader, wire_type, 2) ||
                    !sl_read_slice(reader, &value_data, &value_len)) break;
                if (message->which_work != 4) {
                    volvoxai_v1_submit_batch_work_request_clear_work(message);
                }
                if (!message->field_stateless) {
                    message->field_stateless =
                        (VolvoxaiV1StatelessBatchWork*)message->_allocator->allocate(
                            message->_allocator->context,
                            sizeof(*message->field_stateless));
                    if (!message->field_stateless) return SYNURANG_LITE_OUT_OF_MEMORY;
                    volvoxai_v1_stateless_batch_work_init_with_allocator(
                        message->field_stateless, message->_allocator);
                }
                status = volvoxai_v1_stateless_batch_work_merge_at_depth(
                    message->field_stateless, value_data, value_len,
                    message_depth + 1);
                if (status != SYNURANG_LITE_OK) return status;
                message->which_work = 4;
                break;
            }
            case 5:
            {
                const uint8_t* value_data;
                size_t value_len;
                if (!sl_expect_wire(reader, wire_type, 2) ||
                    !sl_read_slice(reader, &value_data, &value_len)) break;
                if (message->which_work != 5) {
                    volvoxai_v1_submit_batch_work_request_clear_work(message);
                }
                if (!message->field_decode) {
                    message->field_decode =
                        (VolvoxaiV1DecodeBatchWork*)message->_allocator->allocate(
                            message->_allocator->context,
                            sizeof(*message->field_decode));
                    if (!message->field_decode) return SYNURANG_LITE_OUT_OF_MEMORY;
                    volvoxai_v1_decode_batch_work_init_with_allocator(
                        message->field_decode, message->_allocator);
                }
                status = volvoxai_v1_decode_batch_work_merge_at_depth(
                    message->field_decode, value_data, value_len,
                    message_depth + 1);
                if (status != SYNURANG_LITE_OK) return status;
                message->which_work = 5;
                break;
            }
            default:
                if (wire_type == 4 || !sl_skip_field(reader, field_number, wire_type)) {
                    reader->status = SYNURANG_LITE_MALFORMED;
                }
                break;
        }
        if (reader->status != SYNURANG_LITE_OK) break;
    }
    if (tag_result < 0 || reader->status != SYNURANG_LITE_OK) return reader->status;
    return reader->pos == reader->len ? SYNURANG_LITE_OK : SYNURANG_LITE_MALFORMED;
}

