static SynurangLiteStatus volvoxai_v1_tensor_merge_reader(
    VolvoxaiV1Tensor* message,
    SynurangLiteReaderInternal* reader,
    unsigned int message_depth) {
    SynurangLiteStatus status = SYNURANG_LITE_OK;
    uint32_t field_number;
    uint8_t wire_type;
    int tag_result;
    if (!message || !reader) return SYNURANG_LITE_INVALID_ARGUMENT;
    if (message_depth > SYNURANG_LITE_MAX_MESSAGE_DEPTH) {
        return SYNURANG_LITE_MALFORMED;
    }
    (void)status;
    while ((tag_result = sl_read_tag(reader, &field_number, &wire_type)) > 0) {
        switch (field_number) {
            case 1:
            {
                const uint8_t* value_data;
                size_t value_len;
                if (!sl_expect_wire(reader, wire_type, 2) ||
                    !sl_read_slice(reader, &value_data, &value_len)) break;
                status = synurang_lite_bytes_assign(
                    message->_allocator,
                    &message->field_name,
                    value_data,
                    value_len);
                if (status != SYNURANG_LITE_OK) return status;
                break;
            }
            case 2:
            {
                void* appended;
                if (wire_type == 2) {
                    const uint8_t* packed_data;
                    size_t packed_len;
                    SynurangLiteReaderInternal packed;
                    if (!sl_read_slice(reader, &packed_data, &packed_len)) break;
                    sl_reader_init(&packed, packed_data, packed_len);
                    while (packed.pos < packed.len) {
                        status = sl_array_append(
                            message->_allocator,
                            (void**)&message->field_shape.data,
                            &message->field_shape.len,
                            &message->field_shape.cap,
                            sizeof(*message->field_shape.data),
                            &appended);
                        if (status != SYNURANG_LITE_OK) return status;
                        if (!sl_read_int64_raw(
                                &packed,
                                (int64_t*)appended)) break;
                    }
                    if (packed.status != SYNURANG_LITE_OK || packed.pos != packed.len) {
                        reader->status = packed.status == SYNURANG_LITE_OK
                            ? SYNURANG_LITE_MALFORMED : packed.status;
                    }
                } else {
                    status = sl_array_append(
                        message->_allocator,
                        (void**)&message->field_shape.data,
                        &message->field_shape.len,
                        &message->field_shape.cap,
                        sizeof(*message->field_shape.data),
                        &appended);
                    if (status != SYNURANG_LITE_OK) return status;
                    if (!sl_read_int64(
                            reader,
                            wire_type,
                            (int64_t*)appended)) break;
                }
                break;
            }
            case 3:
                if (!sl_read_enum(
                        reader, wire_type, &message->field_dtype)) break;
                break;
            case 5:
            {
                const uint8_t* value_data;
                size_t value_len;
                if (!sl_expect_wire(reader, wire_type, 2) ||
                    !sl_read_slice(reader, &value_data, &value_len)) break;
                if (message->which_payload != 5) {
                    volvoxai_v1_tensor_clear_payload(message);
                }
                status = synurang_lite_bytes_assign(
                    message->_allocator,
                    &message->field_inline,
                    value_data,
                    value_len);
                if (status != SYNURANG_LITE_OK) return status;
                message->which_payload = 5;
                break;
            }
            case 6:
            {
                const uint8_t* value_data;
                size_t value_len;
                if (!sl_expect_wire(reader, wire_type, 2) ||
                    !sl_read_slice(reader, &value_data, &value_len)) break;
                if (message->which_payload != 6) {
                    volvoxai_v1_tensor_clear_payload(message);
                }
                if (!message->field_buffer) {
                    message->field_buffer =
                        (VolvoxaiV1BufferView*)message->_allocator->allocate(
                            message->_allocator->context,
                            sizeof(*message->field_buffer));
                    if (!message->field_buffer) return SYNURANG_LITE_OUT_OF_MEMORY;
                    volvoxai_v1_buffer_view_init_with_allocator(
                        message->field_buffer, message->_allocator);
                }
                status = volvoxai_v1_buffer_view_merge_at_depth(
                    message->field_buffer, value_data, value_len,
                    message_depth + 1);
                if (status != SYNURANG_LITE_OK) return status;
                message->which_payload = 6;
                break;
            }
            case 7:
            {
                const uint8_t* value_data;
                size_t value_len;
                if (!sl_expect_wire(reader, wire_type, 2) ||
                    !sl_read_slice(reader, &value_data, &value_len)) break;
                if (message->which_payload != 7) {
                    volvoxai_v1_tensor_clear_payload(message);
                }
                if (!message->field_borrowed) {
                    message->field_borrowed =
                        (VolvoxaiV1BorrowedBuffer*)message->_allocator->allocate(
                            message->_allocator->context,
                            sizeof(*message->field_borrowed));
                    if (!message->field_borrowed) return SYNURANG_LITE_OUT_OF_MEMORY;
                    volvoxai_v1_borrowed_buffer_init_with_allocator(
                        message->field_borrowed, message->_allocator);
                }
                status = volvoxai_v1_borrowed_buffer_merge_at_depth(
                    message->field_borrowed, value_data, value_len,
                    message_depth + 1);
                if (status != SYNURANG_LITE_OK) return status;
                message->which_payload = 7;
                break;
            }
            default:
                if (wire_type == 4 || !sl_skip_field(reader, field_number, wire_type)) {
                    reader->status = SYNURANG_LITE_MALFORMED;
                }
                break;
        }
        if (reader->status != SYNURANG_LITE_OK) break;
    }
    if (tag_result < 0 || reader->status != SYNURANG_LITE_OK) return reader->status;
    return reader->pos == reader->len ? SYNURANG_LITE_OK : SYNURANG_LITE_MALFORMED;
}

