static SynurangLiteStatus volvoxai_v1_tokenizer_vocabulary_merge_reader(
    VolvoxaiV1TokenizerVocabulary* message,
    SynurangLiteReaderInternal* reader,
    unsigned int message_depth) {
    SynurangLiteStatus status = SYNURANG_LITE_OK;
    uint32_t field_number;
    uint8_t wire_type;
    int tag_result;
    if (!message || !reader) return SYNURANG_LITE_INVALID_ARGUMENT;
    if (message_depth > SYNURANG_LITE_MAX_MESSAGE_DEPTH) {
        return SYNURANG_LITE_MALFORMED;
    }
    (void)status;
    while ((tag_result = sl_read_tag(reader, &field_number, &wire_type)) > 0) {
        switch (field_number) {
            case 1:
            {
                const uint8_t* value_data;
                size_t value_len;
                VolvoxaiV1VocabularyToken* item;
                void* appended;
                if (!sl_expect_wire(reader, wire_type, 2) ||
                    !sl_read_slice(reader, &value_data, &value_len)) break;
                status = sl_array_append(
                    message->_allocator,
                    (void**)&message->field_tokens.data,
                    &message->field_tokens.len,
                    &message->field_tokens.cap,
                    sizeof(*message->field_tokens.data),
                    &appended);
                if (status != SYNURANG_LITE_OK) return status;
                item = (VolvoxaiV1VocabularyToken*)appended;
                volvoxai_v1_vocabulary_token_init_with_allocator(item, message->_allocator);
                {
                    SynurangLiteReaderInternal value_reader;
                    sl_reader_init(&value_reader, value_data, value_len);
                    status = volvoxai_v1_vocabulary_token_merge_reader(
                        item, &value_reader, message_depth + 1);
                }
                if (status != SYNURANG_LITE_OK) return status;
                break;
            }
            default:
                if (wire_type == 4 || !sl_skip_field(reader, field_number, wire_type)) {
                    reader->status = SYNURANG_LITE_MALFORMED;
                }
                break;
        }
        if (reader->status != SYNURANG_LITE_OK) break;
    }
    if (tag_result < 0 || reader->status != SYNURANG_LITE_OK) return reader->status;
    return reader->pos == reader->len ? SYNURANG_LITE_OK : SYNURANG_LITE_MALFORMED;
}

SynurangLiteStatus volvoxai_v1_tokenizer_vocabulary_decode(
    VolvoxaiV1TokenizerVocabulary* message,
    const uint8_t* data,
    size_t len) {
    VolvoxaiV1TokenizerVocabulary temporary;
    SynurangLiteReaderInternal reader;
    SynurangLiteStatus status;
    if (!message || (!data && len != 0)) return SYNURANG_LITE_INVALID_ARGUMENT;
    volvoxai_v1_tokenizer_vocabulary_init_with_allocator(&temporary, message->_allocator);
    sl_reader_init(&reader, data, len);
    status = volvoxai_v1_tokenizer_vocabulary_merge_reader(&temporary, &reader, 0);
    if (status != SYNURANG_LITE_OK) {
        volvoxai_v1_tokenizer_vocabulary_free(&temporary);
        return status;
    }
    volvoxai_v1_tokenizer_vocabulary_free(message);
    *message = temporary;
    return SYNURANG_LITE_OK;
}
VolvoxaiV1VocabularyToken* volvoxai_v1_tokenizer_vocabulary_add_tokens(
    VolvoxaiV1TokenizerVocabulary* message) {
    const SynurangLiteAllocator* allocator;
    VolvoxaiV1VocabularyToken* grown;
    size_t capacity;

    if (!message) return NULL;
    allocator = synurang_lite_allocator_or_default(message->_allocator);
    if (message->field_tokens.len == message->field_tokens.cap) {
        /* The allocator has no realloc, so growth allocates, copies, frees.
         * Doubling keeps repeated appends amortized. */
        capacity = message->field_tokens.cap ? message->field_tokens.cap * 2u : 4u;
        if (capacity < message->field_tokens.cap ||
            capacity > SIZE_MAX / sizeof(*grown)) return NULL;
        grown = (VolvoxaiV1VocabularyToken*)allocator->allocate(
            allocator->context, sizeof(*grown) * capacity);
        if (!grown) return NULL;
        memset(grown, 0, sizeof(*grown) * capacity);
        if (message->field_tokens.len) {
            memcpy(grown, message->field_tokens.data,
                   sizeof(*grown) * message->field_tokens.len);
        }
        synurang_lite_release(allocator, message->field_tokens.data);
        message->field_tokens.data = grown;
        message->field_tokens.cap = capacity;
    }
    {
        VolvoxaiV1VocabularyToken* slot =
            &message->field_tokens.data[message->field_tokens.len];
        memset(slot, 0, sizeof(*slot));
        volvoxai_v1_vocabulary_token_init_with_allocator(slot, allocator);
        message->field_tokens.len++;
        return slot;
    }
}

