static SynurangLiteStatus volvoxai_v1_trace_allocator_memory_merge_reader(
    VolvoxaiV1TraceAllocatorMemory* message,
    SynurangLiteReaderInternal* reader,
    unsigned int message_depth) {
    SynurangLiteStatus status = SYNURANG_LITE_OK;
    uint32_t field_number;
    uint8_t wire_type;
    int tag_result;
    if (!message || !reader) return SYNURANG_LITE_INVALID_ARGUMENT;
    if (message_depth > SYNURANG_LITE_MAX_MESSAGE_DEPTH) {
        return SYNURANG_LITE_MALFORMED;
    }
    (void)status;
    while ((tag_result = sl_read_tag(reader, &field_number, &wire_type)) > 0) {
        switch (field_number) {
            case 1:
            {
                const uint8_t* value_data;
                size_t value_len;
                if (!sl_expect_wire(reader, wire_type, 2) ||
                    !sl_read_slice(reader, &value_data, &value_len)) break;
                status = synurang_lite_bytes_assign(
                    message->_allocator,
                    &message->field_allocator,
                    value_data,
                    value_len);
                if (status != SYNURANG_LITE_OK) return status;
                break;
            }
            case 2:
            {
                const uint8_t* value_data;
                size_t value_len;
                if (!sl_expect_wire(reader, wire_type, 2) ||
                    !sl_read_slice(reader, &value_data, &value_len)) break;
                status = synurang_lite_bytes_assign(
                    message->_allocator,
                    &message->field_backend,
                    value_data,
                    value_len);
                if (status != SYNURANG_LITE_OK) return status;
                break;
            }
            case 3:
                if (!sl_read_enum(
                        reader, wire_type, &message->field_space)) break;
                break;
            case 4:
                if (!sl_read_enum(
                        reader, wire_type, &message->field_inventory)) break;
                break;
            case 5:
                if (!sl_read_uint64(
                        reader, wire_type, &message->field_observation_start_ns)) break;
                break;
            case 6:
                if (!sl_read_uint64(
                        reader, wire_type, &message->field_existing_bytes)) break;
                break;
            case 7:
                if (!sl_read_uint64(
                        reader, wire_type, &message->field_live_bytes)) break;
                break;
            case 8:
                if (!sl_read_uint64(
                        reader, wire_type, &message->field_peak_bytes)) break;
                break;
            case 9:
                if (!sl_read_uint64(
                        reader, wire_type, &message->field_allocated_bytes)) break;
                break;
            case 10:
                if (!sl_read_uint64(
                        reader, wire_type, &message->field_freed_bytes)) break;
                break;
            case 11:
                if (!sl_read_uint64(
                        reader, wire_type, &message->field_dropped_events)) break;
                break;
            case 12:
                if (!sl_read_bool(
                        reader, wire_type, &message->field_accounting_complete)) break;
                break;
            case 13:
                if (!sl_read_enum(
                        reader, wire_type, &message->field_scope)) break;
                break;
            default:
                if (wire_type == 4 || !sl_skip_field(reader, field_number, wire_type)) {
                    reader->status = SYNURANG_LITE_MALFORMED;
                }
                break;
        }
        if (reader->status != SYNURANG_LITE_OK) break;
    }
    if (tag_result < 0 || reader->status != SYNURANG_LITE_OK) return reader->status;
    return reader->pos == reader->len ? SYNURANG_LITE_OK : SYNURANG_LITE_MALFORMED;
}

