static SynurangLiteStatus volvoxai_v1_trace_info_merge_reader(
    VolvoxaiV1TraceInfo* message,
    SynurangLiteReaderInternal* reader,
    unsigned int message_depth) {
    SynurangLiteStatus status = SYNURANG_LITE_OK;
    uint32_t field_number;
    uint8_t wire_type;
    int tag_result;
    if (!message || !reader) return SYNURANG_LITE_INVALID_ARGUMENT;
    if (message_depth > SYNURANG_LITE_MAX_MESSAGE_DEPTH) {
        return SYNURANG_LITE_MALFORMED;
    }
    (void)status;
    while ((tag_result = sl_read_tag(reader, &field_number, &wire_type)) > 0) {
        switch (field_number) {
            case 1:
                if (!sl_read_int64(
                        reader, wire_type, &message->field_trace_id)) break;
                break;
            case 2:
            {
                const uint8_t* value_data;
                size_t value_len;
                if (!sl_expect_wire(reader, wire_type, 2) ||
                    !sl_read_slice(reader, &value_data, &value_len)) break;
                if (!message->field_report) {
                    message->field_report =
                        (VolvoxaiV1OperationReport*)message->_allocator->allocate(
                            message->_allocator->context,
                            sizeof(*message->field_report));
                    if (!message->field_report) return SYNURANG_LITE_OUT_OF_MEMORY;
                    volvoxai_v1_operation_report_init_with_allocator(
                        message->field_report, message->_allocator);
                }
                status = volvoxai_v1_operation_report_merge_at_depth(
                    message->field_report, value_data, value_len,
                    message_depth + 1);
                if (status != SYNURANG_LITE_OK) return status;
                break;
            }
            case 3:
                if (!sl_read_enum(
                        reader, wire_type, &message->field_state)) break;
                break;
            case 4:
                if (!sl_read_enum(
                        reader, wire_type, &message->field_detail)) break;
                break;
            case 5:
                if (!sl_read_bool(
                        reader, wire_type, &message->field_device_timing)) break;
                break;
            case 6:
                if (!sl_read_bool(
                        reader, wire_type, &message->field_memory)) break;
                break;
            case 7:
                if (!sl_read_uint64(
                        reader, wire_type, &message->field_capacity_bytes)) break;
                break;
            case 8:
                if (!sl_read_uint64(
                        reader, wire_type, &message->field_event_count)) break;
                break;
            case 9:
                if (!sl_read_uint64(
                        reader, wire_type, &message->field_dropped_events)) break;
                break;
            case 10:
                if (!sl_read_uint64(
                        reader, wire_type, &message->field_active_operations)) break;
                break;
            case 11:
                if (!sl_read_uint64(
                        reader, wire_type, &message->field_pending_device_intervals)) break;
                break;
            case 12:
                if (!sl_read_uint64(
                        reader, wire_type, &message->field_host_clock_resolution_ns)) break;
                break;
            case 13:
            {
                const uint8_t* value_data;
                size_t value_len;
                VolvoxaiV1TraceDeviceCoverage* item;
                void* appended;
                if (!sl_expect_wire(reader, wire_type, 2) ||
                    !sl_read_slice(reader, &value_data, &value_len)) break;
                status = sl_array_append(
                    message->_allocator,
                    (void**)&message->field_devices.data,
                    &message->field_devices.len,
                    &message->field_devices.cap,
                    sizeof(*message->field_devices.data),
                    &appended);
                if (status != SYNURANG_LITE_OK) return status;
                item = (VolvoxaiV1TraceDeviceCoverage*)appended;
                volvoxai_v1_trace_device_coverage_init_with_allocator(item, message->_allocator);
                {
                    SynurangLiteReaderInternal value_reader;
                    sl_reader_init(&value_reader, value_data, value_len);
                    status = volvoxai_v1_trace_device_coverage_merge_reader(
                        item, &value_reader, message_depth + 1);
                }
                if (status != SYNURANG_LITE_OK) return status;
                break;
            }
            case 14:
            {
                const uint8_t* value_data;
                size_t value_len;
                VolvoxaiV1TraceAllocatorMemory* item;
                void* appended;
                if (!sl_expect_wire(reader, wire_type, 2) ||
                    !sl_read_slice(reader, &value_data, &value_len)) break;
                status = sl_array_append(
                    message->_allocator,
                    (void**)&message->field_allocators.data,
                    &message->field_allocators.len,
                    &message->field_allocators.cap,
                    sizeof(*message->field_allocators.data),
                    &appended);
                if (status != SYNURANG_LITE_OK) return status;
                item = (VolvoxaiV1TraceAllocatorMemory*)appended;
                volvoxai_v1_trace_allocator_memory_init_with_allocator(item, message->_allocator);
                {
                    SynurangLiteReaderInternal value_reader;
                    sl_reader_init(&value_reader, value_data, value_len);
                    status = volvoxai_v1_trace_allocator_memory_merge_reader(
                        item, &value_reader, message_depth + 1);
                }
                if (status != SYNURANG_LITE_OK) return status;
                break;
            }
            default:
                if (wire_type == 4 || !sl_skip_field(reader, field_number, wire_type)) {
                    reader->status = SYNURANG_LITE_MALFORMED;
                }
                break;
        }
        if (reader->status != SYNURANG_LITE_OK) break;
    }
    if (tag_result < 0 || reader->status != SYNURANG_LITE_OK) return reader->status;
    return reader->pos == reader->len ? SYNURANG_LITE_OK : SYNURANG_LITE_MALFORMED;
}

