VolvoxaiV1TraceEvent* volvoxai_v1_trace_page_add_events(
    VolvoxaiV1TracePage* message) {
    const SynurangLiteAllocator* allocator;
    VolvoxaiV1TraceEvent* grown;
    size_t capacity;

    if (!message) return NULL;
    allocator = synurang_lite_allocator_or_default(message->_allocator);
    if (message->field_events.len == message->field_events.cap) {
        /* The allocator has no realloc, so growth allocates, copies, frees.
         * Doubling keeps repeated appends amortized. */
        capacity = message->field_events.cap ? message->field_events.cap * 2u : 4u;
        if (capacity < message->field_events.cap ||
            capacity > SIZE_MAX / sizeof(*grown)) return NULL;
        grown = (VolvoxaiV1TraceEvent*)allocator->allocate(
            allocator->context, sizeof(*grown) * capacity);
        if (!grown) return NULL;
        memset(grown, 0, sizeof(*grown) * capacity);
        if (message->field_events.len) {
            memcpy(grown, message->field_events.data,
                   sizeof(*grown) * message->field_events.len);
        }
        synurang_lite_release(allocator, message->field_events.data);
        message->field_events.data = grown;
        message->field_events.cap = capacity;
    }
    {
        VolvoxaiV1TraceEvent* slot =
            &message->field_events.data[message->field_events.len];
        memset(slot, 0, sizeof(*slot));
        volvoxai_v1_trace_event_init_with_allocator(slot, allocator);
        message->field_events.len++;
        return slot;
    }
}
