void volvoxai_v1_trace_page_free(
    VolvoxaiV1TracePage* message) {
    const SynurangLiteAllocator* allocator;
    size_t i;
    if (!message) return;
    allocator = synurang_lite_allocator_or_default(message->_allocator);
    if (message->field_report) {
        volvoxai_v1_operation_report_free(message->field_report);
        synurang_lite_release(allocator, message->field_report);
    }
    for (i = 0; i < message->field_events.len; ++i) {
        volvoxai_v1_trace_event_free(&message->field_events.data[i]);
    }
    synurang_lite_release(allocator, message->field_events.data);
    for (i = 0; i < message->field_process_memory.len; ++i) {
        volvoxai_v1_memory_snapshot_free(&message->field_process_memory.data[i]);
    }
    synurang_lite_release(allocator, message->field_process_memory.data);
    (void)i;
    memset(message, 0, sizeof(*message));
    message->_allocator = allocator;
}


